// Function for MATLAB Function: '<S217>/NLMPC'
boolean_T proc_control::proc_control_BFGSUpdate(int32_T nvar, real_T Bk[19321],
  const real_T sk_data[], real_T yk_data[], real_T workspace_data[])
{
  real_T curvatureS;
  int32_T b_ix;
  int32_T b_jA;
  int32_T b_tmp;
  int32_T ix;
  int32_T jy;
  boolean_T success;
  proc_control_B.dotSY = 0.0;
  if (nvar >= 1) {
    for (ix = 0; ix < nvar; ix++) {
      proc_control_B.dotSY += sk_data[ix] * yk_data[ix];
    }
  }

  b_tmp = static_cast<uint16_T>(nvar);
  std::memset(&workspace_data[0], 0, static_cast<uint16_T>(nvar) * sizeof(real_T));
  ix = 0;
  jy = (nvar - 1) * 139 + 1;
  for (int32_T b{1}; b <= jy; b += 139) {
    b_ix = (b + nvar) - 1;
    for (b_jA = b; b_jA <= b_ix; b_jA++) {
      int32_T tmp;
      tmp = b_jA - b;
      workspace_data[tmp] += Bk[b_jA - 1] * sk_data[ix];
    }

    ix++;
  }

  curvatureS = 0.0;
  if (nvar >= 1) {
    for (int32_T b{0}; b < nvar; b++) {
      curvatureS += workspace_data[b] * sk_data[b];
    }
  }

  if (proc_control_B.dotSY < 0.2 * curvatureS) {
    proc_control_B.dotSY = 0.8 * curvatureS / (curvatureS - proc_control_B.dotSY);
    for (ix = 0; ix < b_tmp; ix++) {
      yk_data[ix] *= proc_control_B.dotSY;
    }

    if (!(1.0 - proc_control_B.dotSY == 0.0)) {
      for (int32_T b{0}; b < nvar; b++) {
        yk_data[b] += (1.0 - proc_control_B.dotSY) * workspace_data[b];
      }
    }

    proc_control_B.dotSY = 0.0;
    if (nvar >= 1) {
      for (ix = 0; ix < nvar; ix++) {
        proc_control_B.dotSY += sk_data[ix] * yk_data[ix];
      }
    }
  }

  success = ((curvatureS > 2.2204460492503131E-16) && (proc_control_B.dotSY >
              2.2204460492503131E-16));
  if (success) {
    curvatureS = -1.0 / curvatureS;
    if (!(curvatureS == 0.0)) {
      ix = 1;
      for (int32_T b{0}; b < b_tmp; b++) {
        if (workspace_data[b] != 0.0) {
          real_T temp;
          temp = workspace_data[b] * curvatureS;
          b_ix = (nvar + ix) - 1;
          for (b_jA = ix; b_jA <= b_ix; b_jA++) {
            Bk[b_jA - 1] += workspace_data[b_jA - ix] * temp;
          }
        }

        ix += 139;
      }
    }

    proc_control_B.dotSY = 1.0 / proc_control_B.dotSY;
    if (!(proc_control_B.dotSY == 0.0)) {
      b_jA = 1;
      for (ix = 0; ix < b_tmp; ix++) {
        curvatureS = yk_data[ix];
        if (curvatureS != 0.0) {
          curvatureS *= proc_control_B.dotSY;
          b_ix = (nvar + b_jA) - 1;
          for (int32_T b{b_jA}; b <= b_ix; b++) {
            Bk[b - 1] += yk_data[b - b_jA] * curvatureS;
          }
        }

        b_jA += 139;
      }
    }
  }

  return success;
}

